package com.bank.cdn;

import java.util.logging.*;

public class CdnDemo {
    private static final Logger log = Logger.getLogger("CDN");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new BankLogFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Origin origin = new Origin();
        origin.put("/static/logo-v1.png", "LOGO_V1_BYTES");
        origin.put("/static/app.css", "CSS_BYTES");

        Cdn cdn = new Cdn(origin);
        cdn.addEdge("edge-bengaluru");
        cdn.addEdge("edge-mumbai");

        // Rajesh (Bengaluru) requests the logo: first MISS, then HIT
        log.info(() -> "req1 " + cdn.get("edge-bengaluru", "/static/logo-v1.png"));
        log.info(() -> "req2 " + cdn.get("edge-bengaluru", "/static/logo-v1.png"));

        // New logo via versioned URL → fresh object, no stale cache problem
        origin.put("/static/logo-v2.png", "LOGO_V2_BYTES");
        log.info(() -> "new logo " + cdn.get("edge-bengaluru", "/static/logo-v2.png"));

        // Invalidate the CSS path across edges after a change
        origin.put("/static/app.css", "CSS_BYTES_UPDATED");
        cdn.invalidate("/static/app.css");
        log.info(() -> "css after invalidation " + cdn.get("edge-mumbai", "/static/app.css"));

        // Personalized statement must NOT be edge-cached
        String stmt = cdn.getDynamic("/api/statement/SAV2001");
        log.info(() -> "statement (origin only) " + stmt);
    }
}

