// ─── File: CacheEntry.java ───
package com.bank.cdn;

public class CacheEntry {
    private final String body;
    private final long expiryAt;
    public CacheEntry(String body, long ttlMillis) {
        this.body = body; this.expiryAt = System.currentTimeMillis() + ttlMillis;
    }
    public String body() { return body; }
    public boolean isExpired() { return System.currentTimeMillis() > expiryAt; }
}
