import java.util.*;
import java.util.logging.*;

public class Origin {
    private static final Logger log = Logger.getLogger("CDN");
    private final Map<String,String> store = new HashMap<>();
    public void put(String path, String body) { store.put(path, body); }
    public String fetch(String path) {
        log.info(() -> "ORIGIN fetch " + path);   // expensive, far away
        return store.get(path);
    }
}
