// ─── File: EdgeServer.java ───
package com.bank.cdn;

import java.util.*;
import java.util.logging.*;

public class EdgeServer {
    private static final Logger log = Logger.getLogger("CDN");
    private final String id;
    private final Origin origin;
    private final Map<String, CacheEntry> cache = new HashMap<>();
    private static final long TTL = 60_000; // 60s

    public EdgeServer(String id, Origin origin) { this.id = id; this.origin = origin; }

    public String serve(String path) {
        CacheEntry e = cache.get(path);
        if (e != null && !e.isExpired()) {
            log.info(() -> id + " HIT " + path);
            return e.body();
        }
        String body = origin.fetch(path);           // miss → origin
        cache.put(path, new CacheEntry(body, TTL));
        log.info(() -> id + " MISS->cached " + path);
        return body;
    }
    public void invalidate(String path) {
        cache.remove(path);
        log.warning(() -> id + " invalidated " + path);
    }
}
```

