// ─── File: Cdn.java ───
package com.bank.cdn;

import java.util.*;

public class Cdn {
    private final Origin origin;
    private final Map<String, EdgeServer> edges = new LinkedHashMap<>();
    public Cdn(Origin origin) { this.origin = origin; }

    public void addEdge(String id) { edges.put(id, new EdgeServer(id, origin)); }
    public String get(String edgeId, String path) { return edges.get(edgeId).serve(path); }

    // invalidate a path across ALL edges
    public void invalidate(String path) { edges.values().forEach(e -> e.invalidate(path)); }

    // dynamic/personalized content bypasses edge cache → always origin
    public String getDynamic(String path) { return origin.fetch(path); }
}
```
